-- Schema + Basis-Rollen für neue Tenant-DBs (z.B. gradify_user_xyz)
CREATE TABLE IF NOT EXISTS rollen (id BIGSERIAL PRIMARY KEY, name VARCHAR(50) NOT NULL UNIQUE, beschreibung VARCHAR(255));
CREATE TABLE IF NOT EXISTS benutzer (id BIGSERIAL PRIMARY KEY, benutzername VARCHAR(50) NOT NULL UNIQUE, email VARCHAR(100) NOT NULL UNIQUE, passwort_hash VARCHAR(255) NOT NULL, vorname VARCHAR(50) NOT NULL, nachname VARCHAR(50) NOT NULL, mandant_id BIGINT NOT NULL, aktiv BOOLEAN NOT NULL DEFAULT true, letzter_login TIMESTAMP, erstellt_am TIMESTAMP, aktualisiert_am TIMESTAMP);
CREATE TABLE IF NOT EXISTS benutzer_rolle (benutzer_id BIGINT NOT NULL, rolle_id BIGINT NOT NULL, PRIMARY KEY (benutzer_id, rolle_id), FOREIGN KEY (benutzer_id) REFERENCES benutzer(id), FOREIGN KEY (rolle_id) REFERENCES rollen(id));
CREATE TABLE IF NOT EXISTS studenten (id BIGSERIAL PRIMARY KEY, benutzer_id BIGINT NOT NULL UNIQUE, matrikelnummer VARCHAR(20) NOT NULL UNIQUE, geburtsdatum DATE, status VARCHAR(20) NOT NULL DEFAULT 'AKTIV', erstellt_am TIMESTAMP, FOREIGN KEY (benutzer_id) REFERENCES benutzer(id));
INSERT INTO rollen (id, name, beschreibung) VALUES (1, 'ROLE_STUDENT', 'Studierende'), (2, 'ROLE_LEHRENDER', 'Lehrende/Dozenten'), (3, 'ROLE_PRUEFUNGSAMT', 'Prüfungsamt-Mitarbeiter'), (4, 'ROLE_STUDIENGANGLEITUNG', 'Studiengangsleitungen'), (5, 'ROLE_ADMIN', 'System-Administratoren'), (6, 'ROLE_HOCHSCHUL_VERWALTER', 'Hochschul-Verwalter') ON CONFLICT (id) DO NOTHING;
